function rampartSimulate(createStrategy, seed, maxTicks, hooks) {
  "use strict";
  // ---- static tables -------------------------------------------------------
  var TT = [
    { name: "bolt",   cost: 50,  dmg: 26,  period: 8,  range: 300, splash: 0,  slow: 0,  pierce: false, ground: true,  air: true  },
    { name: "cannon", cost: 90,  dmg: 60,  period: 24, range: 260, splash: 90, slow: 0,  pierce: false, ground: true,  air: false },
    { name: "frost",  cost: 70,  dmg: 10,  period: 12, range: 240, splash: 0,  slow: 30, pierce: false, ground: true,  air: true  },
    { name: "lance",  cost: 120, dmg: 180, period: 36, range: 360, splash: 0,  slow: 0,  pierce: true,  ground: true,  air: false },
    { name: "flak",   cost: 80,  dmg: 40,  period: 10, range: 320, splash: 70, slow: 0,  pierce: false, ground: false, air: true  }
  ];
  var TT_INDEX = { bolt: 0, cannon: 1, frost: 2, lance: 3, flak: 4 };
  // enemy types: 0 grunt 1 runner 2 wisp 3 brute 4 splitter 5 mender 6 splitling
  var EN = ["grunt", "runner", "wisp", "brute", "splitter", "mender", "splitling"];
  var E_HP = [60, 40, 50, 150, 90, 70, 0];
  var E_SPD = [10, 20, 12, 6, 8, 8, 12];
  var E_BOUNTY = [4, 4, 6, 9, 6, 7, 1];
  var E_LEAK = [1, 1, 2, 3, 2, 2, 1];
  var E_AIR = [0, 0, 1, 0, 0, 0, 0];
  var E_FIRST = [1, 2, 3, 4, 6, 8];
  var E_WEIGHT = [10, 4, 3, 3, 2, 2 > 1 ? 1 : 1];
  var SLOTS = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  var GROUND = [[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]];
  var AIRL = [[0,6],[21,6],[21,11],[23,11]];

  function buildRoute(pts) {
    var len = 0, i;
    for (i = 1; i < pts.length; i++) len += 100 * (Math.abs(pts[i][0] - pts[i-1][0]) + Math.abs(pts[i][1] - pts[i-1][1]));
    var xs = new Int32Array(len + 1), ys = new Int32Array(len + 1), p = 0;
    xs[0] = pts[0][0] * 100 + 50; ys[0] = pts[0][1] * 100 + 50;
    for (i = 1; i < pts.length; i++) {
      var x0 = pts[i-1][0] * 100 + 50, y0 = pts[i-1][1] * 100 + 50;
      var x1 = pts[i][0] * 100 + 50, y1 = pts[i][1] * 100 + 50;
      var n = Math.abs(x1 - x0) + Math.abs(y1 - y0), sx = Math.sign(x1 - x0), sy = Math.sign(y1 - y0);
      for (var k = 1; k <= n; k++) { p++; xs[p] = x0 + sx * k; ys[p] = y0 + sy * k; }
    }
    return { len: len, xs: xs, ys: ys };
  }
  var ROUTES = [buildRoute(GROUND), buildRoute(AIRL)];

  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }

  var rng = mulberry32(seed | 0);
  var mulCache = [0, 1000];
  function mult(w) { while (mulCache.length <= w) { var l = mulCache.length; mulCache.push(Math.floor(mulCache[l - 1] * 108 / 100)); } return mulCache[w]; }
  function genWave(w) {
    var n = 4 + Math.floor(3 * w / 5), out = [], tot = 0, i, j;
    for (j = 0; j < 6; j++) if (E_FIRST[j] <= w) tot += E_WEIGHT[j];
    for (i = 0; i < n; i++) {
      var r = rng() % tot;
      for (j = 0; j < 6; j++) {
        if (E_FIRST[j] > w) continue;
        if (r < E_WEIGHT[j]) break;
        r -= E_WEIGHT[j];
      }
      out.push(j);
    }
    return out;
  }

  // ---- state ----------------------------------------------------------------
  var strat = createStrategy();
  var hasTarget = strat && typeof strat.target === "function";
  var gold = 250, baseHp = 10, wave = 0, nextId = 1, fallTick = -1, endTick = maxTicks;
  var log = [];
  var turrets = new Array(16);
  for (var s0 = 0; s0 < 16; s0++) turrets[s0] = null;
  var enemies = [];          // ascending id
  var queue = [];            // {tick, wave, idx, type}
  var waves = [null, genWave(1)];

  function armorOf(type, w) { return type === 0 ? Math.floor(w / 4) : (type === 3 ? 6 + w : 0); }
  function makeEnemy(type, w, progress, maxHp) {
    var r = ROUTES[E_AIR[type]];
    var e = { id: nextId++, type: type, wave: w, hp: maxHp, maxHp: maxHp, progress: progress,
              air: E_AIR[type], armor: armorOf(type, w), speed: E_SPD[type], slow: 0, age: 0,
              route: r, x: r.xs[progress], y: r.ys[progress] };
    return e;
  }
  function view(e) {
    return { id: e.id, type: EN[e.type], hp: e.hp, maxHp: e.maxHp, x: e.x, y: e.y, air: e.air,
             armor: e.armor, speed: e.speed, slowed: e.slow > 0 ? 1 : 0, remaining: e.route.len - e.progress };
  }
  function tDmg(tt, tier) { var d = tt.dmg; for (var i = 1; i < tier; i++) d = Math.floor(d * 16 / 10); return d; }
  function tRange(tt, tier) { return tt.range + 30 * (tier - 1); }

  function applyActions(acts) {
    if (!Array.isArray(acts)) return;
    var n = Math.min(32, acts.length);
    for (var i = 0; i < n; i++) {
      var a = acts[i];
      if (!a || typeof a !== "object") continue;
      var s = a.slot;
      if (typeof s !== "number" || !(s >= 0 && s < 16) || Math.floor(s) !== s) continue;
      if (a.op === "build") {
        var ti = TT_INDEX.hasOwnProperty(a.type) ? TT_INDEX[a.type] : -1;
        if (ti < 0 || turrets[s] || gold < TT[ti].cost) continue;
        gold -= TT[ti].cost;
        turrets[s] = { slot: s, ti: ti, tier: 1, spent: TT[ti].cost, cd: 0, x: SLOTS[s][0] * 100 + 50, y: SLOTS[s][1] * 100 + 50 };
        log.push([tick, "B", s, ti]);
        if (hooks && hooks.onAction) hooks.onAction(tick, "B", s, ti);
      } else if (a.op === "upgrade") {
        var t = turrets[s];
        if (!t || t.tier >= 3) continue;
        var c = TT[t.ti].cost * (t.tier === 1 ? 1 : 2);
        if (gold < c) continue;
        gold -= c; t.spent += c; t.tier++;
        log.push([tick, "U", s, t.tier]);
        if (hooks && hooks.onAction) hooks.onAction(tick, "U", s, t.tier);
      } else if (a.op === "sell") {
        var t2 = turrets[s];
        if (!t2) continue;
        gold += Math.floor(t2.spent * 70 / 100);
        turrets[s] = null;
        log.push([tick, "S", s, 0]);
        if (hooks && hooks.onAction) hooks.onAction(tick, "S", s, t2.ti);
      }
    }
  }

  function buildState() {
    var sl = [];
    for (var i = 0; i < 16; i++) {
      var t = turrets[i];
      sl.push({ slot: i, x: SLOTS[i][0], y: SLOTS[i][1], turret: t ? { type: TT[t.ti].name, tier: t.tier, spent: t.spent } : null });
    }
    var ev = [];
    for (var j = 0; j < enemies.length; j++) ev.push(view(enemies[j]));
    var nw = [];
    for (var k = 0; k < waves[wave + 1].length; k++) nw.push(EN[waves[wave + 1][k]]);
    return { tick: tick, wave: wave, gold: gold, baseHp: baseHp, slots: sl, enemies: ev, nextWave: nw };
  }

  var tick = 0, fell = false;
  for (tick = 0; tick < maxTicks; tick++) {
    // 1. wave start
    if (tick >= 20 && (tick - 20) % 40 === 0) {
      wave = (tick - 20) / 40 + 1;
      gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * wave;
      waves[wave + 1] = genWave(wave + 1);
      var acts = strat.plan(buildState());
      applyActions(acts);
      var comp = waves[wave];
      for (var qi = 0; qi < comp.length; qi++) queue.push({ tick: tick + 4 * qi, wave: wave, idx: qi, type: comp[qi] });
      queue.sort(function (a, b) { return a.tick - b.tick || a.wave - b.wave || a.idx - b.idx; });
      waves[wave - 1] = null;
      if (hooks && hooks.onWave) hooks.onWave(tick, wave, comp, waves[wave + 1]);
    }
    // 2. spawn
    while (queue.length && queue[0].tick === tick) {
      var q = queue.shift();
      var ne = makeEnemy(q.type, q.wave, 0, Math.floor(E_HP[q.type] * mult(q.wave) / 1000));
      enemies.push(ne);
      if (hooks && hooks.onSpawn) hooks.onSpawn(tick, ne);
    }
    // 3. move
    var i, e;
    for (i = 0; i < enemies.length; i++) {
      e = enemies[i];
      var sp = e.slow > 0 ? Math.floor(e.speed * 60 / 100) : e.speed;
      e.progress += sp;
      if (e.progress >= e.route.len) {
        e.progress = e.route.len;
        e.x = e.route.xs[e.progress]; e.y = e.route.ys[e.progress];
        baseHp -= E_LEAK[e.type];
        log.push([tick, "L", e.id, baseHp]);
        if (hooks && hooks.onLeak) hooks.onLeak(tick, e, baseHp);
        enemies.splice(i, 1); i--;
        if (baseHp <= 0) { fell = true; break; }
      } else {
        e.x = e.route.xs[e.progress]; e.y = e.route.ys[e.progress];
      }
    }
    if (fell) {
      fallTick = tick; endTick = tick;
      log.push([tick, "F", wave, 0]);
      if (hooks && hooks.onFall) hooks.onFall(tick, wave);
      if (hooks && hooks.onTick) hooks.onTick(tick, enemies, turrets, gold, baseHp, wave);
      break;
    }
    // 4. age & heal
    for (i = 0; i < enemies.length; i++) {
      e = enemies[i];
      e.age++;
      if (e.type === 5 && e.age % 20 === 0) {
        for (var h = 0; h < enemies.length; h++) {
          var o = enemies[h], dx = o.x - e.x, dy = o.y - e.y;
          if (dx * dx + dy * dy <= 22500) o.hp = Math.min(o.maxHp, o.hp + Math.floor(o.maxHp * 8 / 100));
        }
        if (hooks && hooks.onHeal) hooks.onHeal(tick, e);
      }
    }
    // 5. turrets fire
    for (var s = 0; s < 16; s++) {
      var t = turrets[s];
      if (!t) continue;
      if (t.cd > 0) { t.cd--; if (t.cd > 0) continue; }
      var tt = TT[t.ti], rng2 = tRange(tt, t.tier), r2 = rng2 * rng2;
      var cands = [];
      for (i = 0; i < enemies.length; i++) {
        e = enemies[i];
        if (e.air ? !tt.air : !tt.ground) continue;
        var ddx = e.x - t.x, ddy = e.y - t.y;
        if (ddx * ddx + ddy * ddy <= r2) cands.push(e);
      }
      if (!cands.length) continue;
      var tgt = null;
      if (hasTarget) {
        var cv = [];
        for (i = 0; i < cands.length; i++) cv.push(view(cands[i]));
        var pick = strat.target({ slot: s, type: tt.name, tier: t.tier, x: t.x, y: t.y, range: rng2 }, cv);
        for (i = 0; i < cands.length; i++) if (cands[i].id === pick) { tgt = cands[i]; break; }
      }
      if (!tgt) {
        tgt = cands[0];
        for (i = 1; i < cands.length; i++) {
          var c = cands[i];
          if (c.route.len - c.progress < tgt.route.len - tgt.progress) tgt = c;
        }
      }
      var dmg = tDmg(tt, t.tier), hits = null;
      if (tt.splash > 0) {
        var sr2 = tt.splash * tt.splash, tx = tgt.x, ty = tgt.y;
        hits = [];
        for (i = 0; i < enemies.length; i++) {
          e = enemies[i];
          if (e.hp <= 0) continue;
          if (e.air ? !tt.air : !tt.ground) continue;
          var sdx = e.x - tx, sdy = e.y - ty;
          if (sdx * sdx + sdy * sdy <= sr2) {
            e.hp -= tt.pierce ? dmg : Math.max(1, dmg - e.armor);
            if (tt.slow) e.slow = tt.slow;
            hits.push(e.id);
          }
        }
      } else {
        tgt.hp -= tt.pierce ? dmg : Math.max(1, dmg - tgt.armor);
        if (tt.slow) tgt.slow = tt.slow;
      }
      t.cd = tt.period;
      if (hooks && hooks.onShot) hooks.onShot(tick, s, t.ti, t.tier, tgt, hits);
      // remove dead
      var anyDead = false;
      for (i = 0; i < enemies.length; i++) if (enemies[i].hp <= 0) { anyDead = true; break; }
      if (anyDead) {
        var keep = [], born = [];
        for (i = 0; i < enemies.length; i++) {
          e = enemies[i];
          if (e.hp > 0) { keep.push(e); continue; }
          gold += E_BOUNTY[e.type];
          log.push([tick, "K", e.id, s]);
          if (hooks && hooks.onKill) hooks.onKill(tick, e, s);
          if (e.type === 4) {
            var shp = Math.max(1, Math.floor(e.maxHp / 4));
            for (var k = 0; k < 3; k++) {
              var sl2 = makeEnemy(6, e.wave, e.progress, shp);
              born.push(sl2);
              if (hooks && hooks.onSpawn) hooks.onSpawn(tick, sl2, e);
            }
          }
        }
        enemies = keep.concat(born);
      }
    }
    // 6. slow timers
    for (i = 0; i < enemies.length; i++) if (enemies[i].slow > 0) enemies[i].slow--;
    if (hooks && hooks.onTick) hooks.onTick(tick, enemies, turrets, gold, baseHp, wave);
  }

  var json = JSON.stringify(log), hsh = 0x811c9dc5;
  for (var ci = 0; ci < json.length; ci++) { hsh ^= json.charCodeAt(ci); hsh = Math.imul(hsh, 0x01000193); }
  var hex = (hsh >>> 0).toString(16);
  while (hex.length < 8) hex = "0" + hex;
  return { score: Math.round((endTick - 20) * 5 / 2) / 100, fallTick: fallTick, log: log, hash: hex };
}

