      for (var qi = 0; qi < comp.length; qi++) queue.push({ tick: tick + 4 * qi, wave: wave, idx: qi, type: comp[qi] });
      queue.sort(function (a, b) { return a.tick - b.tick || a.wave - b.wave || a.idx - b.idx; });
