            hits.push(e.id);
          }
        }
      } else {
        tgt.hp -= tt.pierce ? dmg : Math.max(1, dmg - tgt.armor);
        if (tt.slow) tgt.slow = tt.slow;
      }
      t.cd = tt.period;
      if (hooks && hooks.onShot) hooks.onShot(tick, s, t.ti, t.tier, tgt, hits);
