function rampartSimulate(createStrategy, seed, maxTicks, hooks) {
  "use strict";
  // ---- static tables -------------------------------------------------------
  var TT = [
    { name: "bolt",   cost: 50,  dmg: 26,  period: 8,  range: 300, splash: 0,  slow: 0,  pierce: false, ground: true,  air: true  },
    { name: "cannon", cost: 90,  dmg: 60,  period: 24, range: 260, splash: 90, slow: 0,  pierce: false, ground: true,  air: false },
    { name: "frost",  cost: 70,  dmg: 10,  period: 12, range: 240, splash: 0,  slow: 30, pierce: false, ground: true,  air: true  },
    { name: "lance",  cost: 120, dmg: 180, period: 36, range: 360, splash: 0,  slow: 0,  pierce: true,  ground: true,  air: false },
    { name: "flak",   cost: 80,  dmg: 40,  period: 10, range: 320, splash: 70, slow: 0,  pierce: false, ground: false, air: true  }
  ];
  var TT_INDEX = { bolt: 0, cannon: 1, frost: 2, lance: 3, flak: 4 };
  // enemy types: 0 grunt 1 runner 2 wisp 3 brute 4 splitter 5 mender 6 splitling
  var EN = ["grunt", "runner", "wisp", "brute", "splitter", "mender", "splitling"];
  var E_HP = [60, 40, 50, 150, 90, 70, 0];
  var E_SPD = [10, 20, 12, 6, 8, 8, 12];
  var E_BOUNTY = [4, 4, 6, 9, 6, 7, 1];
  var E_LEAK = [1, 1, 2, 3, 2, 2, 1];
  var E_AIR = [0, 0, 1, 0, 0, 0, 0];
  var E_FIRST = [1, 2, 3, 4, 6, 8];
  var E_WEIGHT = [10, 4, 3, 3, 2, 2 > 1 ? 1 : 1];
  var SLOTS = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  var GROUND = [[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]];
  var AIRL = [[0,6],[21,6],[21,11],[23,11]];

  function buildRoute(pts) {
    var len = 0, i;
    for (i = 1; i < pts.length; i++) len += 100 * (Math.abs(pts[i][0] - pts[i-1][0]) + Math.abs(pts[i][1] - pts[i-1][1]));
    var xs = new Int32Array(len + 1), ys = new Int32Array(len + 1), p = 0;
    xs[0] = pts[0][0] * 100 + 50; ys[0] = pts[0][1] * 100 + 50;
    for (i = 1; i < pts.length; i++) {
      var x0 = pts[i-1][0] * 100 + 50, y0 = pts[i-1][1] * 100 + 50;
      var x1 = pts[i][0] * 100 + 50, y1 = pts[i][1] * 100 + 50;
      var n = Math.abs(x1 - x0) + Math.abs(y1 - y0), sx = Math.sign(x1 - x0), sy = Math.sign(y1 - y0);
      for (var k = 1; k <= n; k++) { p++; xs[p] = x0 + sx * k; ys[p] = y0 + sy * k; }
    }
    return { len: len, xs: xs, ys: ys };
  }
  var ROUTES = [buildRoute(GROUND), buildRoute(AIRL)];

  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }

  var rng = mulberry32(seed | 0);
  var mulCache = [0, 1000];
  function mult(w) { while (mulCache.length <= w) { var l = mulCache.length; mulCache.push(Math.floor(mulCache[l - 1] * 108 / 100)); } return mulCache[w]; }
  function genWave(w) {
    var n = 4 + Math.floor(3 * w / 5), out = [], tot = 0, i, j;
    for (j = 0; j < 6; j++) if (E_FIRST[j] <= w) tot += E_WEIGHT[j];
    for (i = 0; i < n; i++) {
      var r = rng() % tot;
      for (j = 0; j < 6; j++) {
        if (E_FIRST[j] > w) continue;
        if (r < E_WEIGHT[j]) break;
        r -= E_WEIGHT[j];
      }
      out.push(j);
    }
    return out;
  }

  // ---- state ----------------------------------------------------------------
  var strat = createStrategy();
  var hasTarget = strat && typeof strat.target === "function";
  var gold = 250, baseHp = 10, wave = 0, nextId = 1, fallTick = -1, endTick = maxTicks;
  var log = [];
  var turrets = new Array(16);
  for (var s0 = 0; s0 < 16; s0++) turrets[s0] = null;
  var enemies = [];          // ascending id
  var queue = [];            // {tick, wave, idx, type}
  var waves = [null, genWave(1)];

  function armorOf(type, w) { return type === 0 ? Math.floor(w / 4) : (type === 3 ? 6 + w : 0); }
  function makeEnemy(type, w, progress, maxHp) {
    var r = ROUTES[E_AIR[type]];
    var e = { id: nextId++, type: type, wave: w, hp: maxHp, maxHp: maxHp, progress: progress,
              air: E_AIR[type], armor: armorOf(type, w), speed: E_SPD[type], slow: 0, age: 0,
              route: r, x: r.xs[progress], y: r.ys[progress] };
    return e;
  }
  function view(e) {
    return { id: e.id, type: EN[e.type], hp: e.hp, maxHp: e.maxHp, x: e.x, y: e.y, air: e.air,
             armor: e.armor, speed: e.speed, slowed: e.slow > 0 ? 1 : 0, remaining: e.route.len - e.progress };
  }
  function tDmg(tt, tier) { var d = tt.dmg; for (var i = 1; i < tier; i++) d = Math.floor(d * 16 / 10); return d; }
  function tRange(tt, tier) { return tt.range + 30 * (tier - 1); }

  function applyActions(acts) {
    if (!Array.isArray(acts)) return;
    var n = Math.min(32, acts.length);
    for (var i = 0; i < n; i++) {
      var a = acts[i];
      if (!a || typeof a !== "object") continue;
      var s = a.slot;
      if (typeof s !== "number" || !(s >= 0 && s < 16) || Math.floor(s) !== s) continue;
      if (a.op === "build") {
