        gold -= TT[ti].cost;
        turrets[s] = { slot: s, ti: ti, tier: 1, spent: TT[ti].cost, cd: 0, x: SLOTS[s][0] * 100 + 50, y: SLOTS[s][1] * 100 + 50 };
        log.push([tick, "B", s, ti]);
        if (hooks && hooks.onAction) hooks.onAction(tick, "B", s, ti);
      } else if (a.op === "upgrade") {
        var t = turrets[s];
        if (!t || t.tier >= 3) continue;
        var c = TT[t.ti].cost * (t.tier === 1 ? 1 : 2);
