        gold -= c; t.spent += c; t.tier++;
        log.push([tick, "U", s, t.tier]);
        if (hooks && hooks.onAction) hooks.onAction(tick, "U", s, t.tier);
      } else if (a.op === "sell") {
        var t2 = turrets[s];
        if (!t2) continue;
        gold += Math.floor(t2.spent * 70 / 100);
        turrets[s] = null;
        log.push([tick, "S", s, 0]);
        if (hooks && hooks.onAction) hooks.onAction(tick, "S", s, t2.ti);
      }
    }
  }

  function buildState() {
    var sl = [];
    for (var i = 0; i < 16; i++) {
      var t = turrets[i];
      sl.push({ slot: i, x: SLOTS[i][0], y: SLOTS[i][1], turret: t ? { type: TT[t.ti].name, tier: t.tier, spent: t.spent } : null });
    }
