          }
        }
      } else {
        tgt.hp -= tt.pierce ? dmg : Math.max(1, dmg - tgt.armor);
        if (tt.slow) tgt.slow = tt.slow;
      }
      t.cd = tt.period;
      if (hooks && hooks.onShot) hooks.onShot(tick, s, t.ti, t.tier, tgt, hits);
      // remove dead
      var anyDead = false;
      for (i = 0; i < enemies.length; i++) if (enemies[i].hp <= 0) { anyDead = true; break; }
      if (anyDead) {
        var keep = [], born = [];
        for (i = 0; i < enemies.length; i++) {
          e = enemies[i];
          if (e.hp > 0) { keep.push(e); continue; }
          gold += E_BOUNTY[e.type];
          log.push([tick, "K", e.id, s]);
          if (hooks && hooks.onKill) hooks.onKill(tick, e, s);
          if (e.type === 4) {
            var shp = Math.max(1, Math.floor(e.maxHp / 4));
            for (var k = 0; k < 3; k++) {
              var sl2 = makeEnemy(6, e.wave, e.progress, shp);
              born.push(sl2);
              if (hooks && hooks.onSpawn) hooks.onSpawn(tick, sl2, e);
            }
