  }

  var json = JSON.stringify(log), hsh = 0x811c9dc5;
  for (var ci = 0; ci < json.length; ci++) { hsh ^= json.charCodeAt(ci); hsh = Math.imul(hsh, 0x01000193); }
  var hex = (hsh >>> 0).toString(16);
  while (hex.length < 8) hex = "0" + hex;
  return { score: Math.round((endTick - 20) * 5 / 2) / 100, fallTick: fallTick, log: log, hash: hex };
