// Baseline experiments: fixed build orders by slot coverage.
function mkStatic(order, upgradeAfter) {
  return function () {
    return { plan: function (s) {
      var a = [], g = s.gold;
      for (var i = 0; i < order.length; i++) {
        var o = order[i], sl = s.slots[o[0]];
        if (!sl.turret) { var c = COST[o[1]]; if (g >= c) { a.push({ op: "build", slot: o[0], type: o[1] }); g -= c; } else return a; }
      }
      if (!upgradeAfter) return a;
      for (var tier = 1; tier <= 2; tier++) for (var i = 0; i < order.length; i++) {
        var sl = s.slots[order[i][0]];
        if (sl.turret && sl.turret.tier === tier) { var c = COST[sl.turret.type] * tier; if (g >= c) { a.push({ op: "upgrade", slot: sl.slot }); g -= c; } else return a; }
      }
      return a;
    } };
  };
}
var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
function evalS(name, f, n) {
  var tot = 0, mn = 1e9, mx = 0, t0 = Date.now();
  for (var sd = 1; sd <= n; sd++) { var r = rampartSimulate(f, sd * 7919 + 13, 12020); tot += r.score; mn = Math.min(mn, r.score); mx = Math.max(mx, r.score); }
  print(name.padEnd(28) + " mean " + (tot / n).toFixed(2) + "  min " + mn + "  max " + mx + "  (" + (Date.now() - t0) + " ms)");
}
var byCov = [8, 3, 6, 13, 11, 4, 2, 7, 1, 12, 0, 9, 5, 10, 14, 15];
var N = 40;
["bolt", "cannon", "lance"].forEach(function (t) {
  evalS("all " + t + " +upg", mkStatic(byCov.map(function (s) { return [s, t]; }), true), N);
});
