var mix = [[3,"cannon"],[6,"cannon"],[13,"cannon"],[8,"cannon"],[12,"flak"],[11,"cannon"],[4,"cannon"],[2,"cannon"],[7,"cannon"],[1,"cannon"],[14,"flak"],[0,"cannon"],[9,"cannon"],[5,"cannon"],[10,"flak"],[15,"flak"]];
evalS("mix cannon/flak +upg", mkStatic(mix, true), N);
