function diag(f, seed) {
  var leaks = [], lastGold = 0, lastWave = 0, tur = null, kills = {}, shots = {}, dmgBy = {};
  var r = rampartSimulate(f, seed, 12020, {
    onLeak: function (t, e, hp) { leaks.push("w" + Math.floor((t - 20) / 40 + 1) + ":" + ["grunt","runner","wisp","brute","splitter","mender","splitling"][e.type] + "(w" + e.wave + "," + e.hp + "/" + e.maxHp + ")"); },
    onTick: function (t, en, tu, g, hp, w) { lastGold = g; lastWave = w; tur = tu.map(function (x) { return x ? ["B","C","F","L","K"][x.ti] + x.tier : "--"; }).join(" "); },
    onShot: function (t, s, ti, tier, tgt, hits) { shots[s] = (shots[s] || 0) + 1; }
  });
  print("seed " + seed + " score " + r.score + " wave " + lastWave + " gold " + lastGold);
  print("  turrets: " + tur);
  print("  leaks: " + leaks.join(" "));
  var sh = []; for (var s = 0; s < 16; s++) sh.push(s + ":" + (shots[s] || 0)); print("  shots: " + sh.join(" "));
}

