function cfgStrat(types, P) {
  var base = makeStrat(Object.assign({ seq: [], types: types }, P));
  return function () {
    var s = base();
    return { plan: function (st) { if (st.wave !== 1) return []; var a = []; for (var i = 0; i < 16; i++) if (types[i]) { a.push({ op: "build", slot: i, type: types[i] }); } for (var i = 0; i < 16; i++) if (types[i]) a.push({ op: "upgrade", slot: i }, { op: "upgrade", slot: i }); return a.slice(0, 32).concat([]); }, target: s.target };
  };
}
// note: 16 builds + 32 upgrades > 32 actions; so do builds+upgrades at wave1 and remaining at wave2
function cfgStrat2(types, P) {
  var base = makeStrat(Object.assign({ seq: [], types: types }, P));
  return function () {
    var s = base(), acts = [];
    for (var i = 0; i < 16; i++) if (types[i]) acts.push({ op: "build", slot: i, type: types[i] });
    for (var i = 0; i < 16; i++) if (types[i]) acts.push({ op: "upgrade", slot: i }, { op: "upgrade", slot: i });
    return { plan: function (st) { if (st.wave > 2) return []; return st.wave === 1 ? acts.slice(0, 32) : acts.slice(32); }, target: s.target };
  };
