  var f = cfgStrat2(types, P), tot = 0, mn = 1e9;
  for (var i = 0; i < seeds.length; i++) { var r = simInf(f, seeds[i], 12020); tot += r.score; if (r.score < mn) mn = r.score; }
  return { mean: tot / seeds.length, min: mn };
}

