// Strategy v3: richer targeting. P.tw: per enemy type weight [grunt,runner,wisp,brute,splitter,mender,splitling]
// P.cls: {cannon:{lead,off,kill}, flak:{...}, bolt:{...}, lance:{...}, frost:{...}}
var COST_ = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
function makeStrat(P) {
  return function createStrategy() {
    function route(pts) {
      var len = 0, i; for (i = 1; i < pts.length; i++) len += 100 * (Math.abs(pts[i][0]-pts[i-1][0]) + Math.abs(pts[i][1]-pts[i-1][1]));
      var xs = new Int32Array(len + 1), ys = new Int32Array(len + 1), p = 0;
      xs[0] = pts[0][0]*100+50; ys[0] = pts[0][1]*100+50;
      for (i = 1; i < pts.length; i++) { var x0 = pts[i-1][0]*100+50, y0 = pts[i-1][1]*100+50, x1 = pts[i][0]*100+50, y1 = pts[i][1]*100+50;
        var n = Math.abs(x1-x0)+Math.abs(y1-y0), sx = Math.sign(x1-x0), sy = Math.sign(y1-y0);
        for (var k = 1; k <= n; k++) { p++; xs[p] = x0+sx*k; ys[p] = y0+sy*k; } }
      return { len: len, xs: xs, ys: ys };
    }
    var RG = route([[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]]), RA = route([[0,6],[21,6],[21,11],[23,11]]);
    var DMG = { bolt: [26,41,65], cannon: [60,96,153], frost: [10,16,25], lance: [180,288,460], flak: [40,64,102] };
    var SPL = { cannon: 8100, flak: 4900 };
    var TI = { grunt: 0, runner: 1, wisp: 2, brute: 3, splitter: 4, mender: 5, splitling: 6 };
    var seq = P.seq, types = P.types, TW = P.tw, CLS = P.cls;
    var px = new Float64Array(512), py = new Float64Array(512), val = new Float64Array(512);
    function plan(s) {
      var g = s.gold, a = [];
      var tiers = s.slots.map(function (x) { return x.turret ? x.turret.tier : 0; });
      for (var i = 0; i < seq.length; i++) {
        var sl = seq[i][0], want = seq[i][1], typ = types[sl];
        if (tiers[sl] >= want) continue;
        if (tiers[sl] !== want - 1) continue;
        var c = want === 1 ? COST_[typ] : COST_[typ] * (want - 1);
        if (g < c) break;
        a.push(want === 1 ? { op: "build", slot: sl, type: typ } : { op: "upgrade", slot: sl });
        g -= c; tiers[sl] = want;
        if (a.length >= 32) break;
      }
      return a;
    }
    function target(t, cands) {
      var tp = t.type, dm = DMG[tp][t.tier - 1], C = CLS[tp], n = cands.length, i, j, e, d, best = 0, bs = -1e300;
      if (n > 512) n = 512;
      for (i = 0; i < n; i++) {
        e = cands[i];
        d = tp === "lance" ? dm : (dm - e.armor < 1 ? 1 : dm - e.armor);
        var v = (d >= e.hp ? e.hp + C.kill * e.maxHp : d) * (1 + C.lead * 4600 / (e.remaining + C.off)) * TW[TI[e.type]];
        if (tp === "frost") v = (e.slowed ? 0.05 : 1) * e.hp * (1 + C.lead * 4600 / (e.remaining + C.off)) * TW[TI[e.type]];
        val[i] = v;
      }
      if (tp === "cannon" || tp === "flak") {
        var r2 = SPL[tp];
