// Optimize targeting params on the infinite-gold ceiling. Globals: CHAIN, ITERS, TYPES (config)
var rs = (CHAIN * 2654435761) >>> 0;
function rnd() { rs = (rs + 0x6D2B79F5) | 0; var t = Math.imul(rs ^ (rs >>> 15), 1 | rs); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }
function ri(n) { return Math.floor(rnd() * n); }
var TRAIN = seedList(1000, 48), VALID = seedList(5000, 48);
function clone(o) { return JSON.parse(JSON.stringify(o)); }
var cur = typeof START !== "undefined" ? START : { tw: [1, 1, 1, 1, 1, 1, 1], cls: defCls(BEST4.lead, BEST4.leadOff, BEST4.kill) };
function score(Q, seeds) { return evalInf(TYPES, Q, seeds); }
function mutate(Q) {
  Q = clone(Q); var k = ri(3);
  if (k === 0) { var i = ri(7); Q.tw[i] *= Math.exp((rnd() - 0.5) * 0.8); }
  else { var c = ["cannon", "flak", "bolt"][ri(3)], f = ["lead", "off", "kill"][ri(3)]; Q.cls[c][f] *= Math.exp((rnd() - 0.5) * 1.2); if (Q.cls[c][f] < 0.001) Q.cls[c][f] = 0.001; }
  return Q;
}
var curS = score(cur, TRAIN).mean, best = clone(cur), bestS = curS, t0 = Date.now();
for (var it = 0; it < ITERS; it++) {
  var Q = mutate(cur); if (rnd() < 0.4) Q = mutate(Q);
  var s = score(Q, TRAIN).mean;
  if (s >= curS) { cur = Q; curS = s; if (s > bestS) { best = clone(Q); bestS = s; } }
}
var v = score(best, VALID);
print(JSON.stringify({ chain: CHAIN, train: bestS, valid: v.mean, vmin: v.min, ms: Date.now() - t0, P: best }));

