  var DURATION = 100;
  var TPS = 20;
  var NT = 2020;
  var SEED = 42;

  // ------------------------------------------------------------------------------------------
  // Seeded generators (visual: seed 42, audio: seed 4242). Never Math.random().
  // ------------------------------------------------------------------------------------------
  function mulberry(a) {
    return function () {
      a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  var vrand = mulberry(SEED);
