  var GROUND_PTS = [[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]];
  var AIR_PTS = [[0,6],[21,6],[21,11],[23,11]];
  var KEEP_X = 23.5, KEEP_Z = 11.5;

  var R = (function recordReplay() {
    var tracks = [];
    var tickIds = new Array(NT), tickGold = new Int32Array(NT), tickHp = new Int32Array(NT), tickWave = new Int32Array(NT);
    var shots = [], kills = [], heals = [], leaks = [], actions = [], waves = [], splits = [];
    var fall = null, lastTick = -1;
    var hooks = {
      onAction: function (tick, code, slot, b) { actions.push({ tick: tick, code: code, slot: slot, b: b }); },
      onWave: function (tick, wave, comp, next) { waves.push({ tick: tick, wave: wave, comp: comp.slice(), next: next.slice() }); },
      onSpawn: function (tick, e, parent) {
        tracks[e.id] = { id: e.id, type: e.type, air: e.air, t0: tick, xs: [], ys: [], hp: [], sl: [], end: -1, endKind: 0, ex: 0, ey: 0 };
        if (parent) splits.push({ tick: tick, x: parent.x, y: parent.y, id: parent.id });
      },
      onShot: function (tick, slot, ti, tier, tgt, hits) {
        shots.push({ tick: tick, slot: slot, ti: ti, tier: tier, tid: tgt.id, tx: tgt.x, ty: tgt.y, air: tgt.air, ttype: tgt.type });
      },
      onKill: function (tick, e, slot) {
        kills.push({ tick: tick, id: e.id, type: e.type, x: e.x, y: e.y, air: e.air, slot: slot });
        var tr = tracks[e.id]; tr.end = tick; tr.endKind = 1; tr.ex = e.x; tr.ey = e.y;
      },
      onLeak: function (tick, e, hp) {
        leaks.push({ tick: tick, id: e.id, type: e.type, hp: hp });
        var tr = tracks[e.id]; tr.end = tick; tr.endKind = 2; tr.ex = e.x; tr.ey = e.y;
      },
      onHeal: function (tick, e) { heals.push({ tick: tick, id: e.id, x: e.x, y: e.y }); },
      onFall: function (tick, wave) { fall = { tick: tick, wave: wave }; },
      onTick: function (tick, enemies, turrets, gold, baseHp, wave) {
        var ids = new Int32Array(enemies.length);
        for (var i = 0; i < enemies.length; i++) {
          var e = enemies[i], tr = tracks[e.id];
