function createStrategy() {
  "use strict";
  // ---- tuned constants (found by offline search over many seeds; seed 42 never used) ----
  var TYPES = __TYPES__;            // turret type planned for each slot
  var SEQ = __SEQ__;                // build / upgrade priority list: [slot, tier]
  var TW = __TW__;                  // target value weight per enemy type
  var CLS = __CLS__;                // per turret type: urgency (lead, off) and kill bonus
  var SLM = __SLM__;                // per slot urgency multiplier
  var ADAPT = __ADAPT__;            // adaptive anti-air parameters

  var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
  var DMG = { bolt: [26, 41, 65], cannon: [60, 96, 153], frost: [10, 16, 25], lance: [180, 288, 460], flak: [40, 64, 102] };
  var SPL2 = { cannon: 8100, flak: 4900 };
  var TI = { grunt: 0, runner: 1, wisp: 2, brute: 3, splitter: 4, mender: 5, splitling: 6 };

  // Route geometry (own copy, used to place candidates from their `remaining` distance).
  function route(pts) {
    var len = 0, i;
    for (i = 1; i < pts.length; i++) len += 100 * (Math.abs(pts[i][0] - pts[i - 1][0]) + Math.abs(pts[i][1] - pts[i - 1][1]));
    var xs = new Int32Array(len + 1), ys = new Int32Array(len + 1), p = 0;
    xs[0] = pts[0][0] * 100 + 50; ys[0] = pts[0][1] * 100 + 50;
    for (i = 1; i < pts.length; i++) {
      var x0 = pts[i - 1][0] * 100 + 50, y0 = pts[i - 1][1] * 100 + 50, x1 = pts[i][0] * 100 + 50, y1 = pts[i][1] * 100 + 50;
      var n = Math.abs(x1 - x0) + Math.abs(y1 - y0), sx = x1 > x0 ? 1 : (x1 < x0 ? -1 : 0), sy = y1 > y0 ? 1 : (y1 < y0 ? -1 : 0);
      for (var k = 1; k <= n; k++) { p++; xs[p] = x0 + sx * k; ys[p] = y0 + sy * k; }
    }
    return { len: len, xs: xs, ys: ys };
  }
  var RG = route([[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]]);
  var RA = route([[0, 6], [21, 6], [21, 11], [23, 11]]);
  var px = new Float64Array(1024), py = new Float64Array(1024), val = new Float64Array(1024);

  function tierOf(s, i) {
    var sl = s && s.slots && s.slots[i];
    return sl && sl.turret ? (sl.turret.tier | 0) : 0;
  }
  function typeOf(s, i) {
    var sl = s && s.slots && s.slots[i];
    return sl && sl.turret ? sl.turret.type : null;
  }

  function plan(s) {
    var g = s.gold, acts = [], tiers = [], i;
    for (i = 0; i < 16; i++) tiers.push(tierOf(s, i));
    // repair: a slot holding a different type than planned is left alone (never happens with this plan)
    for (i = 0; i < SEQ.length && acts.length < 32; i++) {
