#!/usr/bin/env python3
"""Assemble ./index.html from dev parts. Usage: build.py params.json report.json out.html"""
import json, sys, re, os

here = os.path.dirname(os.path.abspath(__file__))
params = json.load(open(sys.argv[1]))
report = json.load(open(sys.argv[2]))
out = sys.argv[3]

def js(v):
    return json.dumps(v, separators=(",", ":"))

def rnd(v, n=4):
    if isinstance(v, float):
        return round(v, n)
    if isinstance(v, list):
        return [rnd(x, n) for x in v]
    if isinstance(v, dict):
        return {k: rnd(x, n) for k, x in v.items()}
    return v

strat = open(os.path.join(here, "strategy_template.js")).read()
strat = strat.replace("__TYPES__", js(params["types"]))
strat = strat.replace("__SEQ__", js(params["seq"]))
strat = strat.replace("__TW__", js(rnd(params["tw"])))
cls = {k: {"lead": rnd(v["lead"]), "off": rnd(v["off"]), "kill": rnd(v["kill"])} for k, v in params["cls"].items()}
strat = strat.replace("__CLS__", js(cls))
strat = strat.replace("__SLM__", js(rnd(params.get("slm", [1.0] * 16))))
strat = strat.replace("__ADAPT__", js(rnd(params.get("adapt", {}))))

sim = open(os.path.join(here, "sim.js")).read().strip()
main = open(os.path.join(here, "main.js")).read().strip()
main = main.replace("__BENCH_REPORT__", json.dumps(report, indent=2).replace("\n", "\n  "))
shell = open(os.path.join(here, "shell.html")).read()
html = shell.replace("/*__STRATEGY__*/", strat.strip()).replace("/*__SIM__*/", sim).replace("/*__MAIN__*/", main)
open(out, "w").write(html)
print("wrote", out, len(html), "bytes")

