#!/usr/bin/env python3
import sys, os, json, time, hashlib
from playwright.sync_api import sync_playwright

url, outdir = sys.argv[1], sys.argv[2]
os.makedirs(outdir, exist_ok=True)
JS_SCRUB = "(t) => { const s = document.getElementById('scrubber'); s.value = String(t); s.dispatchEvent(new Event('input', {bubbles:true})); }"
JS_STATE = """() => { const c = document.getElementById('countdown'); const tg = document.getElementById('btn-toggle');
  return { cd: getComputedStyle(c).display, cdText: c.textContent, scrub: document.getElementById('scrubber').value,
           aria: tg.getAttribute('aria-label'), play: getComputedStyle(document.getElementById('icon-play')).display,
           pause: getComputedStyle(document.getElementById('icon-pause')).display }; }"""

def canvas_hash(pg):
    return hashlib.md5(pg.locator("#stage").screenshot()).hexdigest()

with sync_playwright() as p:
    b = p.chromium.launch(headless=True, args=["--use-angle=metal", "--enable-gpu", "--ignore-gpu-blocklist", "--autoplay-policy=no-user-gesture-required"])
    pg = b.new_page(viewport={"width": 1920, "height": 1080})
    logs, reqs = [], []
    pg.on("console", lambda m: logs.append(m.type + ": " + m.text))
    pg.on("pageerror", lambda e: logs.append("PAGEERROR: " + str(e)))
    pg.on("request", lambda r: reqs.append(r.url))
    t0 = time.time()
    pg.goto(url)
    pg.wait_for_function("window.BENCH_REPORT !== undefined", timeout=60000)
    tl = time.time()
    # countdown sampling (wall clock)
    samples = []
    for wait in [300, 1000, 1000, 1000]:
        pg.wait_for_timeout(wait)
        samples.append((round(time.time() - tl, 2), pg.evaluate(JS_STATE)))
    for s in samples: print("t+%.2fs" % s[0], s[1])
    rep = json.loads(pg.evaluate("JSON.stringify(window.BENCH_REPORT)"))
    print("seed42:", rep["seed42"], "testedInBrowser:", rep["testedInBrowser"])
    vec = pg.evaluate("""() => {
      const A = () => ({ plan(s) { const a = []; let g = s.gold; for (const sl of s.slots) if (!sl.turret && g >= 50) { a.push({ op: 'build', slot: sl.slot, type: 'bolt' }); g -= 50; } return a; } });
      const B = () => ({ plan(s) { if (s.wave === 1) return [{op:'build',slot:3,type:'cannon'},{op:'build',slot:6,type:'frost'}];
        if (s.wave === 3) return [{op:'upgrade',slot:3},{op:'build',slot:12,type:'flak'}];
        if (s.wave === 6) return [{op:'build',slot:8,type:'lance'},{op:'sell',slot:6}]; return []; } });
      const ra = rampartSimulate(A, 42, 12020), rb = rampartSimulate(B, 7, 12020), r42 = rampartSimulate(createStrategy, 42, 2020);
      const t0 = performance.now(); let tot = 0; for (let i = 0; i < 20; i++) tot += rampartSimulate(createStrategy, 777 + i * 31, 12020).score;
      return { A: [ra.score, ra.fallTick, ra.log.length, ra.hash], B: [rb.score, rb.fallTick, rb.log.length, rb.hash], s42: [r42.score, r42.fallTick, r42.hash],
               msPerGame: (performance.now() - t0) / 20, mean20: tot / 20 };
    }""")
    print("in-browser vectors:", vec)
    dom = pg.evaluate("""() => ({ canvases: document.querySelectorAll('canvas').length, bodyKids: [...document.body.children].map(e => e.tagName + (e.id ? '#' + e.id : '')).join(','),
       scripts: [...document.scripts].map(s => s.id || (s.src ? 'src' : 'main')).join(',') })""")
    print("dom:", dom)
    # toggle during PLAYING -> PAUSED
    pg.click("#btn-toggle"); print("after toggle (playing->paused):", pg.evaluate(JS_STATE))
    pg.click("#btn-toggle"); print("after toggle (paused->playing):", pg.evaluate(JS_STATE))
    # refire -> hold 1s -> playing
    pg.click("#btn-refire"); st = pg.evaluate(JS_STATE); print("after refire:", st)
    pg.wait_for_timeout(600); print("refire +0.6s:", pg.evaluate(JS_STATE))
    pg.wait_for_timeout(700); print("refire +1.3s:", pg.evaluate(JS_STATE))
    # speed pill
    pg.click(".speed-pill[data-speed='2.0']")
    print("pills:", pg.evaluate("[...document.querySelectorAll('.speed-pill')].map(p => p.dataset.speed + ':' + p.classList.contains('is-active') + ':' + p.getAttribute('aria-checked')).join(' ')"))
    pg.click(".speed-pill[data-speed='1.0']")
    # determinism: scrub paths
    pg.evaluate(JS_SCRUB, 50.0); pg.wait_for_timeout(150); h1 = canvas_hash(pg)
    pg.evaluate(JS_SCRUB, 80.0); pg.wait_for_timeout(150)
    pg.evaluate(JS_SCRUB, 50.0); pg.wait_for_timeout(150); h2 = canvas_hash(pg)
    pg.evaluate(JS_SCRUB, 10.0); pg.wait_for_timeout(150)
    pg.evaluate(JS_SCRUB, 50.0); pg.wait_for_timeout(150); h3 = canvas_hash(pg)
    print("scrub determinism 50.0:", h1 == h2 == h3, h1[:8], h2[:8], h3[:8])
    pg.evaluate(JS_SCRUB, 96.5); pg.wait_for_timeout(150); f1 = canvas_hash(pg)
    pg.evaluate(JS_SCRUB, 30); pg.wait_for_timeout(150)
    pg.evaluate(JS_SCRUB, 96.5); pg.wait_for_timeout(150); f2 = canvas_hash(pg)
    print("scrub determinism 96.5 (post-fall):", f1 == f2)
    print("after scrub:", pg.evaluate(JS_STATE))
    # end: scrub to 99.5 and play -> ENDED
    pg.evaluate(JS_SCRUB, 99.5); pg.click("#btn-toggle"); pg.wait_for_timeout(1000)
    print("after reaching end:", pg.evaluate(JS_STATE))
    pg.click("#btn-toggle"); pg.wait_for_timeout(200)
    print("toggle in ENDED (restart):", pg.evaluate(JS_STATE))
    # fps at busiest section
    for start in [60, 85]:
        fps = pg.evaluate("""(st) => new Promise(res => {
            const s = document.getElementById('scrubber'); s.value = String(st); s.dispatchEvent(new Event('input', {bubbles:true}));
            document.getElementById('btn-toggle').click();
            let n = 0, t0 = performance.now(), worst = 0, last = t0;
            function f() { const now = performance.now(); worst = Math.max(worst, now - last); last = now; n++;
              if (now - t0 < 4000) requestAnimationFrame(f); else { document.getElementById('btn-toggle').click(); res([n / ((now - t0) / 1000), worst]); } }
            requestAnimationFrame(f);
        })""", start)
        print("fps from t=%d: %.1f (worst frame %.1f ms)" % (start, fps[0], fps[1]))
    for t in [0, 30, 75, 92, 95.8, 99]:
        pg.evaluate(JS_SCRUB, t); pg.wait_for_timeout(150)
        pg.screenshot(path=os.path.join(outdir, "final_%05.1f.png" % t))
    pg.set_viewport_size({"width": 1280, "height": 650}); pg.wait_for_timeout(300)
    for t in [55, 96.2]:
        pg.evaluate(JS_SCRUB, t); pg.wait_for_timeout(150)
        pg.screenshot(path=os.path.join(outdir, "small_%05.1f.png" % t))
    print("external requests:", sorted(set(r for r in reqs if not r.startswith("file:"))))
    print("console (%d):" % len(logs))
    for l in logs[:30]: print("  ", l)
    b.close()

